const hashPage=location.hash.startsWith('#/')?location.hash.slice(2):'';
const appState = { page:hashPage==='home'?'public':(hashPage||'public'), language:'en', drawer:false, filter:'', user:null, profile:null, data:structuredClone(seed), busy:false };
const stored = (()=>{try{return JSON.parse(localStorage.getItem('northern-star-demo')||'{}')}catch{return {}}})();
Object.entries(stored).forEach(([key,value])=>{ if(Array.isArray(appState.data[key])) appState.data[key]=value; });
