const app = document.querySelector('#app');
const h = (s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials = s=>String(s||'NS').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const fmt = n=>new Intl.NumberFormat('en-NG',{maximumFractionDigits:0}).format(Number(n)||0);
const cash = n=>'₦'+fmt(n);
const date = s=>s?new Date(s).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'—';
const status = s=>`<span class="status status-${h(String(s||'pending').toLowerCase().replaceAll('_','-'))}"><i></i>${h(String(s||'pending').replaceAll('_',' '))}</span>`;
const level = l=>`<span class="level level-${h(l||'L1')}"><span></span>${h(l||'Unassigned')}</span>`;
const icon = (name)=>({search:'⌕',bell:'♧',arrow:'↗',down:'⌄',plus:'+',filter:'☷',chevron:'›',clock:'◷',pin:'⌖',people:'♙',check:'✓',shield:'◇',chart:'▥',menu:'☰',close:'×',download:'↓',add:'＋',chat:'✉',spark:'✧'})[name]||'·';
const isDemo = !supabase;
function persist(){localStorage.setItem('northern-star-demo',JSON.stringify(appState.data))}
function toast(message,type='success'){const el=document.querySelector('#toast');if(!el)return;el.innerHTML=`<span class="toast-icon">${type==='error'?'!':'✓'}</span>${h(message)}`;el.className='toast show '+type;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='toast',3500)}

async function boot(){
  if(supabase){
    const {data:{session}}=await supabase.auth.getSession();
    if(session){await setSession(session)}
    supabase.auth.onAuthStateChange((_event,session)=>{setSession(session)});
  }
  render();
}
async function setSession(session){
  appState.user=session?.user||null;appState.profile=null;
  if(session&&supabase){const {data}=await supabase.from('profiles').select('*').eq('id',session.user.id).maybeSingle();appState.profile=data;await loadLiveData();if(appState.page==='public')appState.page=data?.role==='participant'?'participant-home':'overview'}
  render();
}
async function loadLiveData(){
  if(!supabase||!appState.user)return;
  const tables=['participants','applications','programs','referrals','partners','surveys','outreach','finance','stories'];
  const dbNames={outreach:'outreach_events',finance:'finance_entries',stories:'impact_stories'};
  await Promise.all(tables.map(async key=>{const {data,error}=await supabase.from(dbNames[key]||key).select('*').order('created_at',{ascending:false}).limit(100);if(!error&&data){appState.data[key]=data}}));
}
function render(){
  const who=appState.profile?.full_name||appState.user?.user_metadata?.full_name||'Programme Admin';
  const staffNav=isDemo||(appState.profile?.role&&appState.profile.role!=='participant');
  app.innerHTML=`<div class="shell ${appState.drawer?'drawer-open':''}">
    <aside class="sidebar"><a class="brand" href="#overview"><span class="brand-mark">N</span><span class="brand-copy"><b>Northern<span>Star</span></b><small>YOUTH EMPOWERMENT</small></span></a>
      <button class="public-portal-link" data-page="public"><span>↗</span> Open applicant portal</button>
      ${staffNav?`<div class="workspace-label">WORKSPACE</div><div class="nav-list">${NAV.map(([label,key,ico])=>`<button class="nav-item ${appState.page===key?'active':''}" data-page="${key}"><span class="nav-icon">${ico}</span><span>${label}</span>${key==='applications'?'<span class="nav-count">12</span>':''}</button>`).join('')}</div>`:''}
      <div class="sidebar-bottom"><div class="pilot-card"><div class="pilot-kicker"><span class="live-dot"></span> PHASE 1 PILOT</div><b>Six-state footprint</b><p>North West · North Central · North East</p><button data-page="reports">View pilot coverage <span>↗</span></button></div>
      <button class="user-profile" data-action="${appState.user?'signout':'auth'}"><span class="avatar">${initials(who)}</span><span class="user-copy"><b>${h(who)}</b><small>${h(appState.profile?.role?.replaceAll('_',' ')||'Workspace access')}</small></span><span class="user-menu">${appState.user?'↪':'···'}</span></button></div>
    </aside><div class="sidebar-scrim" data-action="close-menu"></div>
    <main class="main"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="crumb">Workspace <span>/</span> <b>${h(pageTitle())}</b></div><div class="top-actions"><label class="search-box"><span>${icon('search')}</span><input id="global-search" placeholder="Search participants, applications..." value="${h(appState.filter)}"><kbd>⌘ K</kbd></label><button class="icon-button language-button" data-action="language" aria-label="Change language">文 <span>EN</span></button><button class="icon-button notification-button" data-action="notifications" aria-label="Notifications">♧<i></i></button><span class="top-divider"></span><span class="avatar avatar-small">${initials(who)}</span></div></header>
      ${isDemo?'<div class="demo-bar"><span class="demo-dot"></span><b>Preview mode</b><span>Sample records are stored only in this browser. Connect Supabase to enable secure live data.</span><button data-action="auth">Connect workspace <span>↗</span></button></div>':''}
      <div class="page-wrap"><div id="page-content">${pageContent()}</div></div></main><div id="modal-root"></div><div id="toast" class="toast" role="status"></div></div>`;
  bind();
}
function pageTitle(){return appState.page==='public'?'Applicant portal':appState.page==='participant-home'?'My journey':(NAV.find(x=>x[1]===appState.page)?.[0]||'Overview')}
function heading(title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">NORTHERN NIGERIA YOUTH EMPOWERMENT INITIATIVE</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`}
function button(label,action,kind='primary',ico=''){return `<button class="btn btn-${kind}" data-action="${action}">${ico?`<span>${ico}</span>`:''}${label}</button>`}
function metric(label,value,change,iconName,tone='green',foot='vs last month'){return `<article class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon tone-${tone}">${iconName}</span></div><div class="metric-value">${value}</div><div class="metric-foot"><span class="trend-up">↗ ${change}</span><span>${foot}</span></div></article>`}
function pageContent(){
  const pages={public:publicPage,'participant-home':participantHome,overview:dashboard,participants:participantsPage,applications:applicationsPage,programs:programsPage,field:fieldPage,surveys:surveysPage,referrals:referralsPage,outreach:outreachPage,stories:storiesPage,finance:financePage,messages:messagesPage,reports:reportsPage};
  return (pages[appState.page]||dashboard)();
}
function participantHome(){const mine=appState.data.participants.find(p=>p.user_id===appState.user?.id)||appState.data.participants[0];const applications=appState.data.applications.filter(x=>x.participant_id===mine?.id||x.name===mine?.full_name);return `${heading(`Welcome, ${h((appState.profile?.full_name||mine?.full_name||'there').split(' ')[0])}.`,'Your support journey, next steps and programme updates in one place.',button('Start an application','new-application','primary',icon('plus')))}<section class="participant-welcome"><div><div class="eyebrow">YOUR JOURNEY</div><h2>Every step forward counts.</h2><p>Your pathway can change as your goals and needs evolve. Your assigned team can help you plan what comes next.</p></div><div class="participant-next"><span>UP NEXT</span><b>${h(appState.data.milestones.find(x=>x.status==='in_progress')?.title||'Complete your needs check')}</b><small>Reach out to your programme officer if you need help.</small></div></section><section class="panel participant-ladder"><div class="panel-head"><div><div class="eyebrow">YOUR PROGRESSION LADDER</div><h2>A visible path, at your pace.</h2></div>${level(mine?.current_level||'L1')}</div><div class="journey-ladder wide-ladder">${Object.keys(LEVELS).map((l,i)=>`<span class="journey-step ${l===mine?.current_level?'current':i<Object.keys(LEVELS).indexOf(mine?.current_level||'L1')?'done':''}"><b>${l} · ${LEVELS[l]}</b><small>${l===mine?.current_level?'Current support level':i<Object.keys(LEVELS).indexOf(mine?.current_level||'L1')?'Completed stage':'Possible next stage'}</small></span>`).join('')}</div></section><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><div class="eyebrow">APPLICATIONS</div><h2>Track your applications</h2></div><button class="text-button" data-action="track-application">Find by reference ↗</button></div>${applications.length?applications.map(a=>`<div class="survey-row"><span class="survey-symbol">▤</span><div><b>${h(a.program_name)}</b><small>${h(a.public_ref||a.id)} · Submitted ${date(a.submitted_at||a.created_at)}</small></div>${status(a.status)}</div>`).join(''):'<p class="empty-cell">No applications yet. Start when you are ready.</p>'}</section><section class="panel"><div class="panel-head"><div><div class="eyebrow">MILESTONES</div><h2>Your next steps</h2></div></div>${appState.data.milestones.map(m=>`<div class="milestone"><span class="milestone-check ${m.status==='completed'?'done':''}">${m.status==='completed'?'✓':''}</span><span>${h(m.title)}</span>${status(m.status)}</div>`).join('')}</section></div><section class="panel participant-support"><span>✉</span><div><b>Need support or want to ask a question?</b><small>Send a message to your programme team. Your conversation stays connected to your participant record.</small></div>${button('Message the team','new-message','secondary')}</section>`}
function publicPage(){return `<section class="public-hero"><div class="public-copy"><div class="eyebrow">NORTHERN NIGERIA YOUTH EMPOWERMENT INITIATIVE</div><div class="public-kicker"><span>✦</span> A pathway built around you</div><h1>Your potential deserves<br>a <em>clear path forward.</em></h1><p>Find the support that meets you where you are today—skills, mentorship, recovery services or business growth.</p><div class="public-actions">${button('Start your application','new-application','primary','↗')}${button('Track an existing application','track-application','secondary','⌕')}</div><div class="public-trust"><span>◇</span> Confidential by design <i></i><span>English & Hausa</span><i></i><span>Save and continue</span></div></div><div class="public-visual"><div class="visual-sun"></div><div class="visual-orbit orbit-1"></div><div class="visual-orbit orbit-2"></div><div class="visual-figure"><span class="figure-head"></span><span class="figure-body"></span><span class="figure-arm"></span></div><div class="visual-leaf leaf-1">✦</div><div class="visual-leaf leaf-2">✧</div><div class="visual-note note-a"><span>L2</span><b>Skills & direction</b><small>A step at a time</small></div><div class="visual-note note-b"><span>✦</span><b>Your journey</b><small>Starts with you</small></div><div class="visual-caption">A FUTURE SHAPED BY YOUNG PEOPLE</div></div></section><section class="public-pathways"><div class="section-title"><div><div class="eyebrow">FOUR-LEVEL SUPPORT PATHWAY</div><h2>Meet each young person where they are.</h2><p>A short, respectful needs check helps connect you to the most useful next step.</p></div><span class="section-stamp">01 — 04</span></div><div class="public-level-grid">${Object.entries(LEVELS).map(([l,n],i)=>`<article class="public-level level-card-${l}"><div class="public-level-top"><span>${l}</span><small>0${i+1}</small></div><h3>${n}</h3><p>${['Specialist recovery, therapy, life skills and trusted community support.','Safe spaces, emotional support, mentorship and prevention services.','Skills training, livelihood pathways, business literacy and structured guidance.','Business coaching, networks, market linkages and access to finance.'][i]}</p><span class="level-link">Explore support ↗</span></article>`).join('')}</div></section><section class="public-program"><div><div class="eyebrow">PHASE 1 PILOT</div><h2>Built around real pathways,<br>not generic programmes.</h2><p>The first pilot focuses on NYSC members and recent graduates who are building an income or business and ready to grow.</p><ul><li>Practical coaching and a 90-day growth plan</li><li>Mentors, peer networks and market linkages</li><li>Finance readiness and income tracking</li></ul></div><div class="program-highlight"><span class="program-highlight-mark">✦</span><small>FEATURED PATHWAY</small><h3>NYSC Enterprise<br>Accelerator</h3><p>For serving corps members and recent graduates with a business idea or existing venture.</p>${button('Check your eligibility','new-application','secondary','↗')}</div></section><section class="public-footprint"><div><div class="eyebrow">SIX-STATE PILOT FOOTPRINT</div><h2>Local context.<br>Shared opportunity.</h2><p>Representative states across the North West, North Central and North East help test urban, rural and post-conflict contexts.</p><span class="prototype-note">Prototype assumption: pilot states are placeholders for validation.</span></div><div class="state-chips">${STATES.map((s,i)=>`<span class="state-chip"><i class="state-marker state-${i}"></i>${s}</span>`).join('')}</div></section><section class="public-journey"><div class="eyebrow">SIMPLE BY DESIGN</div><h2>From application to the right support.</h2><div class="journey-cards">${[['01','Tell us about yourself','Complete a mobile-friendly profile with location, NYSC and livelihood information.'],['02','Complete a needs check','A respectful assessment recommends support that matches your needs.'],['03','Follow your progress','Track review, shortlisting and programme enrolment from your personal dashboard.']].map(x=>`<article><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div>${button('Ready to find your next step?','new-application','primary','↗')}</section><footer class="public-footer"><span>© 2026 Northern Nigeria Youth Empowerment Initiative · Prototype</span><div><button data-action="auth">Staff workspace</button><button data-action="security">Privacy & data care</button><a href="mailto:info@northernstar.org.ng">Contact</a></div></footer>`}
